def solve_timeline():
    print("==================================================")
    print("[DEBUG] Z3 Timeline Simulator V2 (Race Condition 원천 차단 모드)")
    print("==================================================")
    
    s = Solver()
    T = [Int(f'T_{i}') for i in range(64)]
    
    # 입력값 범위 (0~f)
    for i in range(64):
        s.add(T[i] >= 0, T[i] <= 15)

    lock_intervals = {}

    # 스레드별 시뮬레이션
    for i, trace in thread_actions.items():
        t = T[i]  
        held_locks = {}
        
        for action, val in trace:
            if action == "sleep":
                if val != -1:  
                    t = t + val
            elif action == "lock":
                held_locks[val] = t
            elif action == "unlock":
                if val in held_locks:
                    start_t = held_locks.pop(val)
                    if val not in lock_intervals:
                        lock_intervals[val] = []
                    lock_intervals[val].append((i, start_t, t))

    conflict_count = 0
    # 모든 락에 대해 교차 점유 점검
    for lock_addr, intervals in lock_intervals.items():
        for (i, start_A, end_A), (j, start_B, end_B) in itertools.combinations(intervals, 2):
            if i != j:
                # [수정된 핵심 로직] 등호(=)를 완전히 제거하여 미만(<) 처리. 
                # 즉, 두 스레드는 동일한 락에 대해 절대 같은 초(Second)의 경계선에 서 있을 수 없음! 
                # 무조건 1초 이상의 버퍼 간격이 강제됨.
                s.add(Or(end_A < start_B, end_B < start_A))
                conflict_count += 1
                
    print(f"[DEBUG] 추가된 엄격한 충돌 방지 제약: {conflict_count}개")
    print("[DEBUG] Solving...")

    if s.check() == sat:
        m = s.model()
        res = [m[T[i]].as_long() for i in range(64)]
        payload = "".join([hex(v)[2:] for v in res])
        print("\n==================================================")
        print("[SUCCESS] 레이스 컨디션이 원천 차단된 진정한 스케줄을 찾았습니다!")
        print(f"[★] PAYLOAD: {payload}")
        print("==================================================")
    else:
        print("\n[ERROR] UNSAT - 0~15 범위 내에서 완벽한 분리가 불가능합니다.")

if __name__ == "__main__":
    solve_timeline()